import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date | null) => void;
}

function startOfDay(date: Date): Date {
  const result = new Date(date);
  result.setHours(0, 0, 0, 0);
  return result;
}

function daysAgo(days: number): Date {
  const date = new Date();
  date.setDate(date.getDate() - days);
  return startOfDay(date);
}

const quickOptions = [
  { value: 'today', label: 'Сегодня', getDate: () => daysAgo(0) },
  { value: 'yesterday', label: 'Вчера', getDate: () => daysAgo(1) },
  { value: 'week', label: 'Неделя назад', getDate: () => daysAgo(7) },
];

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [date, setDate] = useState<Date | null>(null);
  const [activeQuick, setActiveQuick] = useState<string | null>(null);

  const applyDate = (value: Date | null) => {
    setDate(value);
    onChange?.(value);
  };

  const handleQuickSelect = (value: string, getDate: () => Date) => {
    setActiveQuick(value);
    applyDate(getDate());
  };

  const handleCalendarChange = (value: Date | null) => {
    setActiveQuick(null);
    applyDate(value);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <div style={{ display: 'flex', gap: 'var(--jx-r-sm)' }}>
        {quickOptions.map((option) => (
          <JxChip
            key={option.value}
            active={activeQuick === option.value}
            onClick={() => handleQuickSelect(option.value, option.getDate)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={date} onValueChange={handleCalendarChange} />
    </div>
  );
}

